-- Scenario: ETL, bulk loads, admin and maintenance statements
CREATE TABLE IF NOT EXISTS staging_orders (raw_id TEXT, raw_total TEXT, raw_date TEXT);
CREATE TABLE IF NOT EXISTS etl_log (id INTEGER PRIMARY KEY AUTOINCREMENT, step TEXT, rows_affected INTEGER, ran_at TEXT DEFAULT CURRENT_TIMESTAMP);
INSERT INTO orders (id, total, ordered_at) SELECT CAST(raw_id AS INTEGER), CAST(raw_total AS REAL), date(raw_date) FROM staging_orders WHERE raw_id GLOB '[0-9]*';
INSERT INTO etl_log (step, rows_affected) VALUES ('load_orders', changes());
INSERT INTO orders SELECT * FROM orders_backup WHERE id NOT IN (SELECT id FROM orders);
DELETE FROM staging_orders;
DELETE FROM orders WHERE rowid NOT IN (SELECT min(rowid) FROM orders GROUP BY id);
UPDATE orders SET total = round(total, 2), status = lower(trim(status));
UPDATE orders SET (total, status) = (SELECT sum(qty * unit_price), 'recalc' FROM order_items WHERE order_id = orders.id) WHERE id = 1;
UPDATE orders SET total = t.sum FROM (SELECT order_id, sum(qty * unit_price) AS sum FROM order_items GROUP BY order_id) AS t WHERE orders.id = t.order_id;
UPDATE orders AS o SET status = 'vip' FROM customers AS c WHERE c.id = o.customer_id AND c.tier = 'gold';
DROP TABLE IF EXISTS staging_orders;
ALTER TABLE orders ADD COLUMN source TEXT DEFAULT 'import';
CREATE TABLE orders_new (id INTEGER PRIMARY KEY, total REAL NOT NULL, ordered_at TEXT);
INSERT INTO orders_new SELECT id, total, ordered_at FROM orders;
DROP TABLE orders;
ALTER TABLE orders_new RENAME TO orders;
ATTACH DATABASE 'archive.db' AS archive;
ATTACH 'other.db' AS other;
DETACH DATABASE archive;
INSERT INTO archive.orders SELECT * FROM main.orders WHERE ordered_at < '2020-01-01';
SELECT * FROM archive.orders UNION ALL SELECT * FROM main.orders;
PRAGMA foreign_keys = ON;
PRAGMA journal_mode = WAL;
PRAGMA table_info(orders);
PRAGMA user_version;
PRAGMA user_version = 5;
PRAGMA integrity_check;
PRAGMA main.synchronous = NORMAL;
VACUUM INTO 'backup.db';
VACUUM main;
EXPLAIN SELECT * FROM orders WHERE id = 1;
EXPLAIN QUERY PLAN SELECT * FROM orders o JOIN customers c ON c.id = o.customer_id;
REINDEX;
ANALYZE main;
END TRANSACTION;
BEGIN DEFERRED TRANSACTION;
BEGIN EXCLUSIVE;
COMMIT TRANSACTION;
ROLLBACK TO SAVEPOINT sp1;
ROLLBACK TRANSACTION TO sp2;
